// ---------- begin Matrix ----------
package matrix

interface SemiRing<R> {
    fun zero(): R
    fun one(): R
}

class SquareMatrix<R : SemiRing<R>> private constructor(
    private val size: Int,
    private val buf: Array<R>
) {
    companion object {
        fun <R : SemiRing<R>> zero(size: Int, factory: () -> R): SquareMatrix<R> {
            val buf = Array(size * size) { factory() }
            return SquareMatrix(size, buf)
        }

        fun <R : SemiRing<R>> identity(size: Int, factory: () -> R): SquareMatrix<R> {
            val e = zero(size, factory)
            for (i in 0 until size) {
                e.buf[i * size + i] = e.buf[i * size + i].one()
            }
            return e
        }
    }

    fun get(x: Int, y: Int): R {
        require(x < size && y < size)
        return buf[x * size + y]
    }

    fun getMut(x: Int, y: Int): R {
        require(x < size && y < size)
        return buf[x * size + y]
    }

    fun matadd(rhs: SquareMatrix<R>): SquareMatrix<R> {
        require(size == rhs.size)
        val newBuf = Array(size * size) { buf[0].zero() }
        for (i in buf.indices) {
            newBuf[i] = (buf[i] as dynamic + rhs.buf[i] as dynamic) as R
        }
        return SquareMatrix(size, newBuf)
    }

    fun matmul(rhs: SquareMatrix<R>): SquareMatrix<R> {
        val size = this.size
        require(size == rhs.size)
        val res = zero(size) { buf[0].zero() }
        for (x in 0 until size) {
            for (aIndex in 0 until size) {
                val aVal = this.buf[x * size + aIndex]
                for (bIndex in 0 until size) {
                    val idx = x * size + bIndex
                    val bVal = rhs.buf[aIndex * size + bIndex]
                    res.buf[idx] = (res.buf[idx] as dynamic + (aVal as dynamic * bVal as dynamic)) as R
                }
            }
        }
        return res
    }

    fun matPow(n: Long): SquareMatrix<R> {
        var nVar = n
        val size = this.size
        var t = identity(size) { buf[0].one() }
        var s = this.copy()
        while (nVar > 0) {
            if (nVar and 1L == 1L) {
                t = t.matmul(s)
            }
            s = s.matmul(s)
            nVar = nVar shr 1
        }
        return t
    }

    fun copy(): SquareMatrix<R> {
        val newBuf = buf.copyOf()
        return SquareMatrix(size, newBuf)
    }

    fun matsub(rhs: SquareMatrix<R>): SquareMatrix<R> {
        require(size == rhs.size)
        val newBuf = Array(size * size) { buf[0].zero() }
        for (i in buf.indices) {
            newBuf[i] = (buf[i] as dynamic - rhs.buf[i] as dynamic) as R
        }
        return SquareMatrix(size, newBuf)
    }
}
