package modint

interface Modulo {
    fun modulo(): Int
}

interface ConstantModulo {
    val MOD: Int
}

class Mod : ConstantModulo {
    override val MOD: Int = 1_000_000_007
}

object StaticMod : Modulo {
    private var STATIC_MOD: Int = 0
    override fun modulo(): Int = STATIC_MOD
    fun setModulo(p: Int) {
        STATIC_MOD = p
    }
}

class ModInt<T : Modulo>(val value: Int, private val moduloProvider: T) {
    fun clone(): ModInt<T> = ModInt(value, moduloProvider)

    operator fun plus(rhs: ModInt<T>): ModInt<T> {
        var d = value + rhs.value
        val m = moduloProvider.modulo()
        if (d >= m) d -= m
        return ModInt(d, moduloProvider)
    }

    operator fun minus(rhs: ModInt<T>): ModInt<T> {
        val m = moduloProvider.modulo()
        var d = m + value - rhs.value
        if (d >= m) d -= m
        return ModInt(d, moduloProvider)
    }

    operator fun times(rhs: ModInt<T>): ModInt<T> {
        val m = moduloProvider.modulo()
        val v = (value.toLong() * rhs.value.toLong() % m.toLong()).toInt()
        return ModInt(v, moduloProvider)
    }

    operator fun unaryMinus(): ModInt<T> {
        return if (value == 0) zero() else ModInt(moduloProvider.modulo() - value, moduloProvider)
    }

    override fun toString(): String = value.toString()

    fun isZero(): Boolean = value == 0

    fun pow(n: Long): ModInt<T> {
        var nVar = n
        var t = one()
        var s = this
        while (nVar > 0) {
            if (nVar and 1L == 1L) {
                t *= s
            }
            s *= s
            nVar = nVar shr 1
        }
        return t
    }

    fun inv(): ModInt<T> {
        require(value != 0)
        return pow(moduloProvider.modulo().toLong() - 2)
    }

    companion object {
        fun <T : Modulo> newUnchecked(d: Int, moduloProvider: T): ModInt<T> =
            ModInt(d, moduloProvider)

        fun <T : Modulo> zero(moduloProvider: T): ModInt<T> =
            ModInt(0, moduloProvider)

        fun <T : Modulo> one(moduloProvider: T): ModInt<T> =
            ModInt(1, moduloProvider)

        fun <T : Modulo> new(d: Int, moduloProvider: T): ModInt<T> =
            ModInt(d % moduloProvider.modulo(), moduloProvider)
    }
}

operator fun <T : Modulo> ModInt<T>.plusAssign(rhs: ModInt<T>) {
    val res = this + rhs
    (this as dynamic).value = res.value
}

operator fun <T : Modulo> ModInt<T>.minusAssign(rhs: ModInt<T>) {
    val res = this - rhs
    (this as dynamic).value = res.value
}

operator fun <T : Modulo> ModInt<T>.timesAssign(rhs: ModInt<T>) {
    val res = this * rhs
    (this as dynamic).value = res.value
}

fun modPow(r: Long, n: Long, m: Long): Long {
    var nVar = n
    var t = 1L % m
    var s = r % m
    while (nVar > 0) {
        if (nVar and 1L == 1L) {
            t = t * s % m
        }
        s = s * s % m
        nVar = nVar shr 1
    }
    return t
}
// ---------- end ModInt ----------
