import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import matrix.*
import modint.*

typealias M = ModInt<Mod>
typealias Mat = SquareMatrix<M>

fun main() {
    run()
}

fun run() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(reader.readLine())
    val w = IntArray(7) { st.nextToken().toInt() }

    val modProvider = Mod()
    val matList = mutableListOf<Mat>()
    for (i in 1..7) {
        val size = 1 shl i
        var m = SquareMatrix.zero(size) { M.newUnchecked(0, modProvider) }
        for (j in 0 until (1 shl i)) {
            for (k in 0 until (1 shl (2 * i - 1))) {
                if (j and k > 0) continue
                var next = 0
                for (x in 0 until i) {
                    val left = x == 0 || (k shr (i + x - 1) and 1) == 1
                    val down = (k shr x and 1) == 1
                    val right = x == i - 1 || (k shr (i + x) and 1) == 1
                    if (left && down && right) {
                        next = next or (1 shl x)
                    }
                }
                val idx = next * size + j
                m = SquareMatrix(
                    size,
                    m.run {
                        val newBuf = Array(size * size) { buf[0] }
                        System.arraycopy(buf, 0, newBuf, 0, buf.size)
                        newBuf[idx] = newBuf[idx] + M.one(modProvider)
                        newBuf
                    }
                )
            }
        }
        matList.add(m)
        m = SquareMatrix.zero(size) { M.newUnchecked(0, modProvider) }
        for (j in 0 until size) {
            val idx = j * size + j
            m = SquareMatrix(
                size,
                m.run {
                    val newBuf = Array(size * size) { buf[0] }
                    System.arraycopy(buf, 0, newBuf, 0, buf.size)
                    newBuf[idx] = M.one(modProvider)
                    newBuf
                }
            )
        }
        matList.add(m)
    }

    fun mul(m: Mat, b: Array<M>): Array<M> {
        val res = Array(b.size) { M.zero(modProvider) }
        for (i in b.indices) {
            for (j in b.indices) {
                res[i] = res[i] + m.get(i, j) * b[j]
            }
        }
        return res
    }

    var b = Array(1 shl 7) { M.zero(modProvider) }
    var ini = false
    val wMut = w.copyOf()
    for (idx in 6 downTo 0) {
        val i = idx
        val wVal = wMut[i]
        val mats = matList.subList(2 * i, 2 * i + 2)
        if (!ini && wMut[i] > 0) {
            wMut[i]--
            ini = true
            val ii = i + 1
            for (k in 0 until (1 shl (ii - 1))) {
                var bit = 0
                for (x in 0 until ii) {
                    val left = x == 0 || (k shr (x - 1) and 1) == 1
                    val down = true
                    val right = x == ii - 1 || (k shr x and 1) == 1
                    if (left && right && down) {
                        bit = bit or (1 shl x)
                    }
                }
                b[bit] = b[bit] + M.one(modProvider)
            }
        }
        b = mul(mats[1], b)
        val powMat = mats[0].matPow(wMut[i].toLong())
        b = mul(powMat, b)
        b = b.copyOf(1 shl (i + 1))
    }
    val ans = b[0]
    println(ans)
}

