interface SemiRing<R> {
    fun zero(): R
    fun one(): R
}

class SquareMatrix<R : SemiRing<R>> private constructor(
    private val size: Int,
    private val buf: Array<R>
) {
    companion object {
        fun <R : SemiRing<R>> zero(size: Int, factory: () -> R): SquareMatrix<R> {
            val buf = Array(size * size) { factory().zero() }
            return SquareMatrix(size, buf)
        }

        fun <R : SemiRing<R>> identity(size: Int, factory: () -> R): SquareMatrix<R> {
            val e = zero(size, factory)
            for (i in 0 until size) {
                e.buf[i * size + i] = factory().one()
            }
            return e
        }
    }

    fun get(x: Int, y: Int): R {
        require(x < size && y < size)
        return buf[x * size + y]
    }

    fun getMut(x: Int, y: Int): R {
        require(x < size && y < size)
        return buf[x * size + y]
    }

    fun set(x: Int, y: Int, value: R) {
        require(x < size && y < size)
        buf[x * size + y] = value
    }

    fun matadd(rhs: SquareMatrix<R>): SquareMatrix<R> {
        require(size == rhs.size)
        val newBuf = Array(size * size) { buf[0].zero() }
        for (i in buf.indices) {
            newBuf[i] = buf[i] + rhs.buf[i]
        }
        return SquareMatrix(size, newBuf)
    }

    fun matmul(rhs: SquareMatrix<R>): SquareMatrix<R> {
        val size = this.size
        require(size == rhs.size)
        val res = zero(size) { buf[0] }
        for (row in 0 until size) {
            for (col in 0 until size) {
                var value = buf[0].zero()
                for (k in 0 until size) {
                    value += this.get(row, k) * rhs.get(k, col)
                }
                res.set(row, col, value)
            }
        }
        return res
    }

    fun matPow(n: Int): SquareMatrix<R> {
        var nVar = n
        val size = this.size
        var t = identity(size) { buf[0] }
        var s = this.cloneMatrix()
        while (nVar > 0) {
            if (nVar and 1 == 1) {
                t = t.matmul(s)
            }
            s = s.matmul(s)
            nVar = nVar shr 1
        }
        return t
    }

    fun matsub(rhs: SquareMatrix<R>): SquareMatrix<R> where R : Subtractable<R> {
        require(size == rhs.size)
        val newBuf = Array(size * size) { buf[0].zero() }
        for (i in buf.indices) {
            newBuf[i] = buf[i] - rhs.buf[i]
        }
        return SquareMatrix(size, newBuf)
    }

    private fun cloneMatrix(): SquareMatrix<R> {
        val newBuf = buf.copyOf()
        return SquareMatrix(size, newBuf)
    }
}

interface Subtractable<R> {
    operator fun minus(other: R): R
}
