interface Modulo {
    fun modulo(): Int
}

interface ConstantModulo {
    val MOD: Int
}

class Mod : ConstantModulo {
    override val MOD: Int = 1_000_000_007
}

object StaticMod : Modulo {
    private var STATIC_MOD: Int = 0
    override fun modulo(): Int = STATIC_MOD
    fun setModulo(p: Int) {
        STATIC_MOD = p
    }
}

class ModInt<T : Modulo>(
    val value: Int,
    private val moduloProvider: T
) : SemiRing<ModInt<T>>, Subtractable<ModInt<T>> {

    override fun zero(): ModInt<T> = ModInt(0, moduloProvider)
    override fun one(): ModInt<T> = ModInt(1, moduloProvider)

    operator fun plus(rhs: ModInt<T>): ModInt<T> {
        var d = this.value + rhs.value
        val m = moduloProvider.modulo()
        if (d >= m) d -= m
        return ModInt(d, moduloProvider)
    }

    operator fun minus(rhs: ModInt<T>): ModInt<T> {
        val m = moduloProvider.modulo()
        var d = m + this.value - rhs.value
        if (d >= m) d -= m
        return ModInt(d, moduloProvider)
    }

    operator fun times(rhs: ModInt<T>): ModInt<T> {
        val m = moduloProvider.modulo()
        val v = (this.value.toLong() * rhs.value.toLong() % m.toLong()).toInt()
        return ModInt(v, moduloProvider)
    }

    operator fun unaryMinus(): ModInt<T> {
        val m = moduloProvider.modulo()
        return if (value == 0) zero() else ModInt(m - value, moduloProvider)
    }

    fun isZero(): Boolean = value == 0

    fun pow(n: Long): ModInt<T> {
        var nVar = n
        var t = one()
        var s = this
        while (nVar > 0) {
            if (nVar and 1L == 1L) {
                t *= s
            }
            s *= s
            nVar = nVar shr 1
        }
        return t
    }

    fun inv(): ModInt<T> {
        require(value != 0)
        val m = moduloProvider.modulo()
        return pow(m.toLong() - 2)
    }

    operator fun plusAssign(rhs: ModInt<T>) {
        val res = this + rhs
        this.valueRef = res.value
    }

    operator fun minusAssign(rhs: ModInt<T>) {
        val res = this - rhs
        this.valueRef = res.value
    }

    operator fun timesAssign(rhs: ModInt<T>) {
        val res = this * rhs
        this.valueRef = res.value
    }

    private var valueRef: Int = value

    override fun toString(): String = value.toString()
}

fun <T : Modulo> modPow(r: Long, n: Long, m: Long): Long {
    var nVar = n
    var t = 1L % m
    var s = r % m
    while (nVar > 0) {
        if (nVar and 1L == 1L) {
            t = t * s % m
        }
        s = s * s % m
        nVar = nVar shr 1
    }
    return t
}
// ---------- end ModInt ----------
// ---------- begin Precalc ----------
class Precalc<T : Modulo>(
    private val moduloProvider: T,
    n: Int
) {
    private val inv: Array<ModInt<T>>
    private val fact: Array<ModInt<T>>
    private val ifact: Array<ModInt<T>>

    init {
        inv = Array(n + 1) { ModInt(1, moduloProvider) }
        fact = Array(n + 1) { ModInt(1, moduloProvider) }
        ifact = Array(n + 1) { ModInt(1, moduloProvider) }
        for (i in 2..n) {
            fact[i] = fact[i - 1] * ModInt(i, moduloProvider)
        }
        ifact[n] = fact[n].inv()
        if (n > 0) {
            inv[n] = ifact[n] * fact[n - 1]
        }
        for (i in n - 1 downTo 1) {
            ifact[i] = ifact[i + 1] * ModInt(i + 1, moduloProvider)
            inv[i] = ifact[i] * fact[i - 1]
        }
    }

    fun inv(n: Int): ModInt<T> {
        require(n > 0)
        return inv[n]
    }

    fun fact(n: Int): ModInt<T> = fact[n]

    fun ifact(n: Int): ModInt<T> = ifact[n]

    fun perm(n: Int, k: Int): ModInt<T> {
        if (k > n) return ModInt(0, moduloProvider)
        return fact[n] * ifact[n - k]
    }

    fun comb(n: Int, k: Int): ModInt<T> {
        if (k > n) return ModInt(0, moduloProvider)
        return fact[n] * ifact[k] * ifact[n - k]
    }
}
// ---------- end Precalc ----------

typealias M = ModInt<Mod>
typealias Mat = SquareMatrix<M>

fun run() {
    val reader = System.`in`.bufferedReader()
    val tokens = reader.readLine().trim().split(" ").map { it.toInt() }.toMutableList()
    val w = tokens

    val modProvider = Mod()
    val matList = mutableListOf<Mat>()
    for (i in 1..7) {
        val size = 1 shl i
        var m = SquareMatrix.zero(size) { M(0, modProvider) }
        for (j in 0 until (1 shl i)) {
            for (k in 0 until (1 shl (2 * i - 1))) {
                if (j and k > 0) continue
                var next = 0
                for (x in 0 until i) {
                    val left = x == 0 || (k shr (i + x - 1)) and 1 == 1
                    val down = (k shr x) and 1 == 1
                    val right = x == i - 1 || (k shr (i + x)) and 1 == 1
                    if (left && down && right) {
                        next = next or (1 shl x)
                    }
                }
                val current = m.getMut(next, j)
                val updated = current + M(1, modProvider)
                m.set(next, j, updated)
            }
        }
        matList.add(m)
        m = SquareMatrix.zero(size) { M(0, modProvider) }
        for (j in 0 until size) {
            m.set(j, j, M(1, modProvider))
        }
        matList.add(m)
    }

    fun mul(m: Mat, b: Array<M>): Array<M> {
        val res = Array(b.size) { M(0, modProvider) }
        for (i in b.indices) {
            var sum = M(0, modProvider)
            for (j in b.indices) {
                sum += m.get(i, j) * b[j]
            }
            res[i] = sum
        }
        return res
    }

    var b = Array(1 shl 7) { M(0, modProvider) }
    var ini = false
    val wMut = w
    for (idx in 6 downTo 0) {
        val i = idx
        val wi = wMut[i]
        val mats = listOf(matList[2 * i], matList[2 * i + 1])
        var wVal = wi
        if (!ini && wVal > 0) {
            wVal -= 1
            wMut[i] = wVal
            ini = true
            val ii = i + 1
            for (k in 0 until (1 shl (ii - 1))) {
                var bit = 0
                for (x in 0 until ii) {
                    val left = x == 0 || (k shr (x - 1)) and 1 == 1
                    val down = true
                    val right = x == ii - 1 || (k shr x) and 1 == 1
                    if (left && right && down) {
                        bit = bit or (1 shl x)
                    }
                }
                b[bit] = b[bit] + M(1, modProvider)
            }
        }
        b = mul(mats[1], b)
        val powMat = mats[0].matPow(wVal)
        b = mul(powMat, b)
        b = b.copyOf(1 shl (i + 1))
    }
    val ans = b[0]
    println(ans)
}

fun main() {
    run()
}

