package matrix

interface SemiRing<R> {
    fun zero(): R
    fun one(): R
}

class SquareMatrix<R>(
    val size: Int,
    private val buf: Array<R>
) {
    companion object {
        fun <R> zero(size: Int, zeroProvider: () -> R): SquareMatrix<R> {
            val arr = Array(size * size) { zeroProvider() }
            return SquareMatrix(size, arr)
        }

        fun <R> identity(size: Int, zeroProvider: () -> R, oneProvider: () -> R): SquareMatrix<R> {
            val m = zero(size, zeroProvider)
            for (i in 0 until size) {
                m.buf[i * size + i] = oneProvider()
            }
            return m
        }
    }

    fun get(x: Int, y: Int): R {
        require(x < size && y < size)
        return buf[x * size + y]
    }

    fun getMut(x: Int, y: Int): R {
        require(x < size && y < size)
        return buf[x * size + y]
    }

    fun set(x: Int, y: Int, value: R) {
        require(x < size && y < size)
        buf[x * size + y] = value
    }

    fun matadd(rhs: SquareMatrix<R>, add: (R, R) -> R): SquareMatrix<R> {
        require(size == rhs.size)
        val newBuf = Array(size * size) { buf[0] }
        for (i in buf.indices) {
            newBuf[i] = add(buf[i], rhs.buf[i])
        }
        return SquareMatrix(size, newBuf)
    }

    fun matmul(
        rhs: SquareMatrix<R>,
        zeroProvider: () -> R,
        add: (R, R) -> R,
        mul: (R, R) -> R
    ): SquareMatrix<R> {
        val n = size
        require(n == rhs.size)
        val res = zero(n, zeroProvider)
        for (row in 0 until n) {
            for (col in 0 until n) {
                var acc = zeroProvider()
                for (k in 0 until n) {
                    val a = this.get(row, k)
                    val b = rhs.get(k, col)
                    acc = add(acc, mul(a, b))
                }
                res.set(row, col, acc)
            }
        }
        return res
    }

    fun matPow(
        n: Long,
        zeroProvider: () -> R,
        oneProvider: () -> R,
        add: (R, R) -> R,
        mul: (R, R) -> R
    ): SquareMatrix<R> {
        var exp = n
        val size = this.size
        var t = identity(size, zeroProvider, oneProvider)
        var s = this.copy()
        var current = t
        while (exp > 0) {
            if ((exp and 1L) == 1L) {
                current = t.matmul(s, zeroProvider, add, mul)
                t = current
            }
            s = s.matmul(s, zeroProvider, add, mul)
            exp = exp shr 1
        }
        return t
    }

    fun copy(): SquareMatrix<R> {
        return SquareMatrix(size, buf.copyOf())
    }

    fun matsub(rhs: SquareMatrix<R>, sub: (R, R) -> R): SquareMatrix<R> {
        require(size == rhs.size)
        val newBuf = Array(size * size) { buf[0] }
        for (i in buf.indices) {
            newBuf[i] = sub(buf[i], rhs.buf[i])
        }
        return SquareMatrix(size, newBuf)
    }
}
