class ModInt<T : Modulo>(
    val value: Int,
    private val moduloProvider: T
) {
    fun clone(): ModInt<T> {
        return ModInt(value, moduloProvider)
    }

    operator fun plus(rhs: ModInt<T>): ModInt<T> {
        var d = this.value + rhs.value
        val m = moduloProvider.modulo()
        if (d >= m) {
            d -= m
        }
        return ModInt(d, moduloProvider)
    }

    operator fun minus(rhs: ModInt<T>): ModInt<T> {
        val m = moduloProvider.modulo()
        var d = m + this.value - rhs.value
        if (d >= m) {
            d -= m
        }
        return ModInt(d, moduloProvider)
    }

    operator fun times(rhs: ModInt<T>): ModInt<T> {
        val m = moduloProvider.modulo()
        val v = (this.value.toLong() * rhs.value.toLong() % m.toLong()).toInt()
        return ModInt(v, moduloProvider)
    }

    operator fun unaryMinus(): ModInt<T> {
        return if (this.value == 0) {
            zero(moduloProvider)
        } else {
            val m = moduloProvider.modulo()
            ModInt(m - this.value, moduloProvider)
        }
    }

    override fun toString(): String {
        return value.toString()
    }

    fun pow(n: Long): ModInt<T> {
        var exp = n
        var t = one(moduloProvider)
        var s = this
        var current = t
        while (exp > 0) {
            if ((exp and 1L) == 1L) {
                current = t * s
                t = current
            }
            s *= s
            exp = exp shr 1
        }
        return t
    }

    fun inv(): ModInt<T> {
        require(this.value != 0)
        val m = moduloProvider.modulo()
        return this.pow(m.toLong() - 2)
    }

    operator fun plusAssign(rhs: ModInt<T>) {
        val res = this + rhs
        this.valueField = res.value
    }

    operator fun minusAssign(rhs: ModInt<T>) {
        val res = this - rhs
        this.valueField = res.value
    }

    operator fun timesAssign(rhs: ModInt<T>) {
        val res = this * rhs
        this.valueField = res.value
    }

    private var valueField: Int = value

    companion object {
        fun <T : Modulo> newUnchecked(d: Int, moduloProvider: T): ModInt<T> {
            return ModInt(d, moduloProvider)
        }

        fun <T : Modulo> zero(moduloProvider: T): ModInt<T> {
            return ModInt(0, moduloProvider)
        }

        fun <T : Modulo> one(moduloProvider: T): ModInt<T> {
            return ModInt(1, moduloProvider)
        }

        fun <T : Modulo> new(d: Int, moduloProvider: T): ModInt<T> {
            val m = moduloProvider.modulo()
            return ModInt(d % m, moduloProvider)
        }

        fun <T : Modulo> fromLong(valLong: Long, moduloProvider: T): ModInt<T> {
            val m = moduloProvider.modulo().toLong()
            return ModInt((valLong % m).toInt(), moduloProvider)
        }

        fun <T : Modulo> fromInt(valInt: Int, moduloProvider: T): ModInt<T> {
            val m = moduloProvider.modulo()
            return ModInt(valInt % m, moduloProvider)
        }

        fun <T : Modulo> fromString(s: String, moduloProvider: T): ModInt<T> {
            val v = s.toInt()
            return new(v, moduloProvider)
        }
    }
}

fun modPow(r: Long, n: Long, m: Long): Long {
    var exp = n
    var t = 1L % m
    var s = r % m
    var current = t
    while (exp > 0) {
        if ((exp and 1L) == 1L) {
            current = t * s % m
            t = current
        }
        s = s * s % m
        exp = exp shr 1
    }
    return t
}
