class Precalc<T : Modulo>(
    private val moduloProvider: T,
    private val inv: Array<ModInt<T>>,
    private val fact: Array<ModInt<T>>,
    private val ifact: Array<ModInt<T>>
) {
    companion object {
        fun <T : Modulo> new(n: Int, moduloProvider: T): Precalc<T> {
            val inv = Array(n + 1) { ModInt.one(moduloProvider) }
            val fact = Array(n + 1) { ModInt.one(moduloProvider) }
            val ifact = Array(n + 1) { ModInt.one(moduloProvider) }
            for (i in 2..n) {
                fact[i] = fact[i - 1] * ModInt.newUnchecked(i, moduloProvider)
            }
            ifact[n] = fact[n].inv()
            if (n > 0) {
                inv[n] = ifact[n] * fact[n - 1]
            }
            for (i in (1 until n).reversed()) {
                ifact[i] = ifact[i + 1] * ModInt.newUnchecked(i + 1, moduloProvider)
                inv[i] = ifact[i] * fact[i - 1]
            }
            return Precalc(moduloProvider, inv, fact, ifact)
        }
    }

    fun inv(n: Int): ModInt<T> {
        require(n > 0)
        return inv[n]
    }

    fun fact(n: Int): ModInt<T> {
        return fact[n]
    }

    fun ifact(n: Int): ModInt<T> {
        return ifact[n]
    }

    fun perm(n: Int, k: Int): ModInt<T> {
        if (k > n) {
            return ModInt.zero(moduloProvider)
        }
        return fact[n] * ifact[n - k]
    }

    fun comb(n: Int, k: Int): ModInt<T> {
        if (k > n) {
            return ModInt.zero(moduloProvider)
        }
        return fact[n] * ifact[k] * ifact[n - k]
    }
