            val arr = Array(size * size) { semiRing.zero() }
            return SquareMatrix(size, arr)
        }

        fun <R> identity(size: Int, semiRing: SemiRing<R>): SquareMatrix<R> {
            val e = zero(size, semiRing)
            for (i in 0 until size) {
                e.buf[i * size + i] = semiRing.one()
            }
