        val size = this.size
        require(size == rhs.size)
        val res = zero(size, semiRing)
        for (row in 0 until size) {
            for (col in 0 until size) {
                var acc = semiRing.zero()
                for (k in 0 until size) {
                    val a = this.get(row, k)
                    val b = rhs.get(k, col)
                    acc = add(acc, mul(a, b))
                }
                res.set(row, col, acc)
            }
        }
        return res
    }

    fun matPow(n: Long, semiRing: SemiRing<R>, add: (R, R) -> R, mul: (R, R) -> R): SquareMatrix<R> {
        var nVar = n
        val size = this.size
        var t = identity(size, semiRing)
        var s = this
        while (nVar > 0) {
            if (nVar and 1L == 1L) {
                t = t.matmul(s, semiRing, add, mul)
