package modint

import kotlin.properties.Delegates

interface Modulo {
    fun modulo(): Int
}

interface ConstantModulo {
    val MOD: Int
}

class Mod : ConstantModulo {
    override val MOD: Int = 1_000_000_007
}

class StaticMod : Modulo {
    companion object {
        var STATIC_MOD: Int by Delegates.notNull()
        fun setModulo(p: Int) {
            STATIC_MOD = p
        }
    }

    override fun modulo(): Int {
        return STATIC_MOD
    }
}

class ModInt<T : Modulo>(
    val value: Int,
    private val modProvider: T
) {
    fun clone(): ModInt<T> = ModInt(value, modProvider)

    operator fun plus(rhs: ModInt<T>): ModInt<T> {
        var d = value + rhs.value
        val m = modProvider.modulo()
        if (d >= m) d -= m
        return ModInt(d, modProvider)
    }

    operator fun minus(rhs: ModInt<T>): ModInt<T> {
        val m = modProvider.modulo()
        var d = m + value - rhs.value
        if (d >= m) d -= m
        return ModInt(d, modProvider)
    }

    operator fun times(rhs: ModInt<T>): ModInt<T> {
        val m = modProvider.modulo()
        val v = (value.toLong() * rhs.value.toLong() % m.toLong()).toInt()
        return ModInt(v, modProvider)
    }

    operator fun unaryMinus(): ModInt<T> {
        return if (value == 0) zero(modProvider) else ModInt(modProvider.modulo() - value, modProvider)
    }

    override fun toString(): String = value.toString()

    fun pow(n: Long): ModInt<T> {
        var nVar = n
        var t = one(modProvider)
        var s = this
        while (nVar > 0) {
            if (nVar and 1L == 1L) {
                t *= s
            }
            s *= s
            nVar = nVar shr 1
        }
        return t
    }

    fun inv(): ModInt<T> {
        require(value != 0)
        return pow(modProvider.modulo().toLong() - 2)
    }

    operator fun plusAssign(rhs: ModInt<T>) {
        val res = this + rhs
        thisRef.value = res.value
    }

    operator fun minusAssign(rhs: ModInt<T>) {
        val res = this - rhs
        thisRef.value = res.value
    }

    operator fun timesAssign(rhs: ModInt<T>) {
        val res = this * rhs
        thisRef.value = res.value
    }

    private val thisRef: ModInt<T> get() = this

    companion object {
        fun <T : Modulo> newUnchecked(d: Int, modProvider: T): ModInt<T> {
            return ModInt(d, modProvider)
        }

        fun <T : Modulo> zero(modProvider: T): ModInt<T> {
            return ModInt(0, modProvider)
        }

        fun <T : Modulo> one(modProvider: T): ModInt<T> {
            return ModInt(1, modProvider)
        }

        fun <T : Modulo> new(d: Int, modProvider: T): ModInt<T> {
            val m = modProvider.modulo()
            return ModInt(d % m, modProvider)
        }

        fun <T : Modulo> fromLong(valLong: Long, modProvider: T): ModInt<T> {
            val m = modProvider.modulo().toLong()
            return ModInt(((valLong % m + m) % m).toInt(), modProvider)
        }
    }
}

fun modPow(r: Long, n: Long, m: Long): Long {
    var nVar = n
    var t = 1L % m
    var s = r % m
    while (nVar > 0) {
        if (nVar and 1L == 1L) {
            t = t * s % m
        }
        s = s * s % m
        nVar = nVar shr 1
    }
    return t
}
