import modint.ModInt
import modint.Modulo

class Precalc<T : Modulo>(
    private val inv: Array<ModInt<T>>,
    private val fact: Array<ModInt<T>>,
    private val ifact: Array<ModInt<T>>
) {
    companion object {
        fun <T : Modulo> new(n: Int, modProvider: T): Precalc<T> {
            val inv = Array(n + 1) { ModInt.one(modProvider) }
            val fact = Array(n + 1) { ModInt.one(modProvider) }
            val ifact = Array(n + 1) { ModInt.one(modProvider) }
            for (i in 2..n) {
                fact[i] = fact[i - 1] * ModInt.newUnchecked(i, modProvider)
            }
            ifact[n] = fact[n].inv()
            if (n > 0) {
                inv[n] = ifact[n] * fact[n - 1]
            }
            for (i in (1 until n).reversed()) {
                ifact[i] = ifact[i + 1] * ModInt.newUnchecked(i + 1, modProvider)
                inv[i] = ifact[i] * fact[i - 1]
            }
            return Precalc(inv, fact, ifact)
        }
    }

    fun inv(n: Int): ModInt<T> {
        require(n > 0)
        return inv[n]
    }

    fun fact(n: Int): ModInt<T> = fact[n]

    fun ifact(n: Int): ModInt<T> = ifact[n]

    fun perm(n: Int, k: Int): ModInt<T> {
        if (k > n) return ModInt.zero(fact[0].modProvider)
        return fact[n] * ifact[n - k]
    }

    fun comb(n: Int, k: Int): ModInt<T> {
        if (k > n) return ModInt.zero(fact[0].modProvider)
        return fact[n] * ifact[k] * ifact[n - k]
    }
}
