fun main() {
    val reader = System.`in`.bufferedReader()
    val w = reader.readLine().trim().split(" ").map { it.toInt() }.toMutableList()

    val modProvider = Mod()
    val semiRing = MSemiRing(modProvider)

    val matList = mutableListOf<Mat>()
    for (i in 1..7) {
        var m = SquareMatrix.zero(1 shl i, semiRing)
        for (j in 0 until (1 shl i)) {
            for (k in 0 until (1 shl (2 * i - 1))) {
                if ((j and k) > 0) continue
                var next = 0
                for (x in 0 until i) {
                    val left = x == 0 || (k shr (i + x - 1) and 1) == 1
                    val down = (k shr x and 1) == 1
                    val right = x == i - 1 || (k shr (i + x) and 1) == 1
                    if (left && down && right) {
                        next = next or (1 shl x)
                    }
                }
                val idx = next * m.size + j
                val cur = m.get(next, j)
                m.set(next, j, cur + ModInt.one(modProvider))
            }
        }
        matList.add(m)
        m = SquareMatrix.zero(1 shl i, semiRing)
        for (j in 0 until (1 shl i)) {
            m.set(j, j, ModInt.one(modProvider))
        }
        matList.add(m)
    }

    fun mul(m: Mat, b: Array<M>): Array<M> {
        val res = Array(b.size) { ModInt.zero(modProvider) }
        for (i in b.indices) {
            var acc = ModInt.zero(modProvider)
            for (j in b.indices) {
                acc += m.get(i, j) * b[j]
            }
            res[i] = acc
        }
        return res
    }

    var b = Array(1 shl 7) { ModInt.zero(modProvider) }
    var ini = false
    for (idx in 6 downTo 0) {
        val i = idx
        val wVal = w[i]
        val mats = listOf(matList[2 * i], matList[2 * i + 1])
        if (!ini && wVal > 0) {
            w[i] = wVal - 1
            ini = true
            val ii = i + 1
            for (k in 0 until (1 shl (ii - 1))) {
                var bit = 0
                for (x in 0 until ii) {
                    val left = x == 0 || (k shr (x - 1) and 1) == 1
                    val down = true
                    val right = x == ii - 1 || (k shr x and 1) == 1
                    if (left && right && down) {
                        bit = bit or (1 shl x)
                    }
                }
                b[bit] = b[bit] + ModInt.one(modProvider)
            }
        }
        b = mul(mats[1], b)
        val powMat = mats[0].matPow(w[i].toLong(), semiRing,
            { a, c -> a + c },
            { a, c -> a * c }
        )
        b = mul(powMat, b)
        b = b.copyOf(1 shl (i + 1))
    }
    val ans = b[0]
    println(ans)
