interface SemiRing<R> {
    fun zero(): R
    fun one(): R
    operator fun plus(other: R): R
    operator fun times(other: R): R
}

class SquareMatrix<R : Any>(
    val size: Int,
    private val buf: Array<R>
) {
    companion object {
        fun <R : Any> zero(size: Int, zeroProvider: () -> R): SquareMatrix<R> {
            val buf = Array(size * size) { zeroProvider() }
            return SquareMatrix(size, buf)
        }

        fun <R : Any> identity(size: Int, zeroProvider: () -> R, oneProvider: () -> R): SquareMatrix<R> {
            val e = zero(size, zeroProvider)
            for (i in 0 until size) {
                e.buf[i * size + i] = oneProvider()
            }
            return e
        }
    }

    fun get(x: Int, y: Int): R {
        require(x < size && y < size)
        return buf[x * size + y]
    }

    fun getMut(x: Int, y: Int): R {
        require(x < size && y < size)
        return buf[x * size + y]
    }

    fun set(x: Int, y: Int, value: R) {
        require(x < size && y < size)
        buf[x * size + y] = value
    }

    fun matadd(rhs: SquareMatrix<R>, add: (R, R) -> R): SquareMatrix<R> {
        require(size == rhs.size)
        val newBuf = Array(size * size) { idx ->
            add(this.buf[idx], rhs.buf[idx])
        }
        return SquareMatrix(size, newBuf)
    }

    fun matmul(rhs: SquareMatrix<R>, zeroProvider: () -> R, add: (R, R) -> R, mul: (R, R) -> R): SquareMatrix<R> {
        val size = this.size
        require(size == rhs.size)
        val res = zero(size, zeroProvider)
        var rowStart = 0
        var aRowStart = 0
        while (rowStart < res.buf.size) {
            val xRow = res.buf
            val aRow = this.buf.copyOfRange(aRowStart, aRowStart + size)
            var bColStart = 0
            for (aVal in aRow) {
                var xIdx = rowStart
                var bIdx = bColStart
                while (bIdx < bColStart + size) {
                    xRow[xIdx] = add(xRow[xIdx], mul(aVal, rhs.buf[bIdx]))
                    xIdx++
                    bIdx++
                }
                bColStart += size
            }
            rowStart += size
            aRowStart += size
        }
        return res
    }

    fun matPow(n: Int, zeroProvider: () -> R, oneProvider: () -> R, add: (R, R) -> R, mul: (R, R) -> R): SquareMatrix<R> {
        var nVar = n
        val size = this.size
        var t = identity(size, zeroProvider, oneProvider)
        var s = SquareMatrix(size, buf.copyOf())
        while (nVar > 0) {
            if (nVar and 1 == 1) {
                t = t.matmul(s, zeroProvider, add, mul)
            }
            s = s.matmul(s, zeroProvider, add, mul)
            nVar = nVar shr 1
        }
        return t
    }

    fun matsub(rhs: SquareMatrix<R>, sub: (R, R) -> R): SquareMatrix<R> {
        require(size == rhs.size)
        val newBuf = Array(size * size) { idx ->
            sub(this.buf[idx], rhs.buf[idx])
        }
        return SquareMatrix(size, newBuf)
    }
}
