class SquareMatrix<R>(
    val size: Int,
    private val buf: Array<R>
) {
    companion object {
        fun <R> zero(size: Int, zeroProvider: () -> R): SquareMatrix<R> {
            val arr = Array(size * size) { zeroProvider() }
            return SquareMatrix(size, arr)
        }

        fun <R> identity(size: Int, zeroProvider: () -> R, oneProvider: () -> R): SquareMatrix<R> {
            val e = zero(size, zeroProvider)
            for (i in 0 until size) {
                e.buf[i * size + i] = oneProvider()
            }
            return e
        }
    }

    fun get(x: Int, y: Int): R {
        require(x < size && y < size)
        return buf[x * size + y]
    }

    fun getMut(x: Int, y: Int): R {
        require(x < size && y < size)
        return buf[x * size + y]
    }

    fun set(x: Int, y: Int, value: R) {
        require(x < size && y < size)
        buf[x * size + y] = value
    }

    fun matadd(rhs: SquareMatrix<R>, add: (R, R) -> R): SquareMatrix<R> {
        require(size == rhs.size)
        val newBuf = Array(size * size) { buf[0] }
        for (i in buf.indices) {
            newBuf[i] = add(buf[i], rhs.buf[i])
        }
        return SquareMatrix(size, newBuf)
    }

    fun matmul(rhs: SquareMatrix<R>, zero: () -> R, add: (R, R) -> R, mul: (R, R) -> R): SquareMatrix<R> {
        val size = this.size
        require(size == rhs.size)
        val res = zero(size, zero)
        val resBuf = res.buf
        val aBuf = this.buf
        val bBuf = rhs.buf
        for (row in 0 until size) {
            val rowOffset = row * size
            for (k in 0 until size) {
                val a = aBuf[rowOffset + k]
                val bRowOffset = k * size
                for (col in 0 until size) {
                    val idx = rowOffset + col
                    resBuf[idx] = add(resBuf[idx], mul(a, bBuf[bRowOffset + col]))
                }
            }
        }
        return res
    }

    fun matPow(n: Long, zero: () -> R, one: () -> R, add: (R, R) -> R, mul: (R, R) -> R): SquareMatrix<R> {
        var nVar = n
        val size = this.size
        var t = identity(size, zero, one)
        var s = SquareMatrix(size, buf.copyOf())
        while (nVar > 0) {
            if ((nVar and 1L) == 1L) {
                t = t.matmul(s, zero, add, mul)
            }
            s = s.matmul(s, zero, add, mul)
            nVar = nVar shr 1
        }
        return t
    }

    fun matsub(rhs: SquareMatrix<R>, sub: (R, R) -> R): SquareMatrix<R> {
        require(size == rhs.size)
        val newBuf = Array(size * size) { buf[0] }
        for (i in buf.indices) {
            newBuf[i] = sub(buf[i], rhs.buf[i])
        }
        return SquareMatrix(size, newBuf)
    }
