interface SemiRing<R> {
    fun zero(): R
    fun one(): R
}

class SquareMatrix<R>(
    val size: Int,
    private val buf: Array<R>
) {
    companion object {
        fun <R> zero(size: Int, zeroProvider: () -> R): SquareMatrix<R> {
            @Suppress("UNCHECKED_CAST")
            val arr = java.lang.reflect.Array.newInstance(
                zeroProvider().javaClass,
                size * size
            ) as Array<R>
            for (i in arr.indices) arr[i] = zeroProvider()
            return SquareMatrix(size, arr)
        }
    }

    fun get(x: Int, y: Int): R {
        require(x < size && y < size)
        return buf[x * size + y]
    }

    fun set(x: Int, y: Int, value: R) {
        require(x < size && y < size)
        buf[x * size + y] = value
    }

    fun matadd(rhs: SquareMatrix<R>, add: (R, R) -> R): SquareMatrix<R> {
        require(size == rhs.size)
        val res = buf.copyOf()
        for (i in buf.indices) {
            res[i] = add(buf[i], rhs.buf[i])
        }
        return SquareMatrix(size, res)
    }

    fun matmul(
        rhs: SquareMatrix<R>,
        zero: () -> R,
        add: (R, R) -> R,
        mul: (R, R) -> R
    ): SquareMatrix<R> {
        val n = size
        require(n == rhs.size)
        val res = Array(buf.size) { zero() }
        for (row in 0 until n) {
            for (col in 0 until n) {
                var acc = zero()
                for (k in 0 until n) {
                    val a = buf[row * n + k]
                    val b = rhs.buf[k * n + col]
                    acc = add(acc, mul(a, b))
                }
                res[row * n + col] = acc
            }
        }
        return SquareMatrix(n, res)
    }

    fun matPow(
        n: Long,
        identity: () -> SquareMatrix<R>,
        zero: () -> R,
        add: (R, R) -> R,
        mul: (R, R) -> R
    ): SquareMatrix<R> {
        var exp = n
        var t = identity()
        var s = this
        while (exp > 0) {
            if ((exp and 1L) == 1L) {
                t = t.matmul(s, zero, add, mul)
            }
            s = s.matmul(s, zero, add, mul)
            exp = exp shr 1
        }
        return t
    }

    fun matsub(rhs: SquareMatrix<R>, sub: (R, R) -> R): SquareMatrix<R> {
        require(size == rhs.size)
        val res = buf.copyOf()
        for (i in buf.indices) {
            res[i] = sub(buf[i], rhs.buf[i])
        }
        return SquareMatrix(size, res)
    }
}
