class ModInt<T : Modulo>(
    val value: Int,
    private val modProvider: T
) {
    fun clone(): ModInt<T> = ModInt(value, modProvider)

    operator fun plus(rhs: ModInt<T>): ModInt<T> {
        var d = value + rhs.value
        val m = modProvider.modulo()
        if (d >= m) d -= m
        return ModInt(d, modProvider)
    }

    operator fun minus(rhs: ModInt<T>): ModInt<T> {
        val m = modProvider.modulo()
        var d = m + value - rhs.value
        if (d >= m) d -= m
        return ModInt(d, modProvider)
    }

    operator fun times(rhs: ModInt<T>): ModInt<T> {
        val m = modProvider.modulo()
        val v = (value.toLong() * rhs.value.toLong() % m.toLong()).toInt()
        return ModInt(v, modProvider)
    }

    operator fun unaryMinus(): ModInt<T> {
        val m = modProvider.modulo()
        return if (value == 0) zero(modProvider) else ModInt(m - value, modProvider)
    }

    override fun toString(): String = value.toString()

    fun pow(n: Long): ModInt<T> {
        var exp = n
        var t = one(modProvider)
        var s = this
        while (exp > 0) {
            if ((exp and 1L) == 1L) {
                t *= s
            }
            s *= s
            exp = exp shr 1
        }
        return t
    }

    fun inv(): ModInt<T> {
        require(value != 0)
        val m = modProvider.modulo()
        return pow(m.toLong() - 2)
    }

    operator fun plusAssign(rhs: ModInt<T>) {
        val res = this + rhs
        fieldSetter(res)
    }

    operator fun minusAssign(rhs: ModInt<T>) {
        val res = this - rhs
        fieldSetter(res)
    }

    operator fun timesAssign(rhs: ModInt<T>) {
        val res = this * rhs
        fieldSetter(res)
    }

    private fun fieldSetter(other: ModInt<T>) {
        val field = this::class.java.getDeclaredField("value")
        field.isAccessible = true
        field.setInt(this, other.value)
    }

    companion object {
        fun <T : Modulo> new(value: Int, modProvider: T): ModInt<T> {
            val m = modProvider.modulo()
            val v = ((value % m) + m) % m
            return ModInt(v, modProvider)
        }

        fun <T : Modulo> zero(modProvider: T): ModInt<T> = ModInt(0, modProvider)
        fun <T : Modulo> one(modProvider: T): ModInt<T> = ModInt(1, modProvider)

        fun <T : Modulo> fromLong(value: Long, modProvider: T): ModInt<T> {
            val m = modProvider.modulo().toLong()
            val v = ((value % m + m) % m).toInt()
            return ModInt(v, modProvider)
        }
    }
}

fun modPow(r: Long, n: Long, m: Long): Long {
    var exp = n
    var t = 1L % m
    var s = r % m
    while (exp > 0) {
        if ((exp and 1L) == 1L) {
            t = t * s % m
        }
        s = s * s % m
        exp = exp shr 1
    }
    return t
}
